INSERT INTO site_content (id, content) VALUES ('forsale.hero.lead', '<strong>The same skis and tritoons we run on the bay,</strong> sold straight off our docks. Every unit is serviced by our crew before it changes hands, and priced well under buying new or from a dealer.') ON CONFLICT (id) DO UPDATE SET content = '<strong>The same skis and tritoons we run on the bay,</strong> sold straight off our docks. Every unit is serviced by our crew before it changes hands, and priced well under buying new or from a dealer.', updated_at = now();
